  // ---------------- Panel B: total cost bars ----------------
  const costData = [
    { label: "Logged (as-run)", value: 87.5194, colorVar: "--series-logged" },
    { label: "Baseline", value: 75.6839, colorVar: "--series-base" },
    { label: "Our router", value: 54.0248, colorVar: "--series-ours" },
  ];

  (function renderBars() {
    const svg = document.getElementById("bars");
    const W = 900, H = 260;
    const M = { top: 20, right: 24, bottom: 40, left: 52 };
    const plotW = W - M.left - M.right, plotH = H - M.top - M.bottom;
    const maxV = Math.max(...costData.map(d => d.value));
    const yScale = v => M.top + (1 - v / (maxV * 1.15)) * plotH;

    [0, 20, 40, 60, 80].forEach(v => {
      const y = yScale(v);
      el("line", { x1: M.left, x2: W - M.right, y1: y, y2: y, class: "grid-line" }, svg);
      el("text", { x: M.left - 8, y: y + 3.5, class: "tick-label", "text-anchor": "end" }, svg).textContent = "$" + v;
    });
    el("line", { x1: M.left, x2: M.left, y1: M.top, y2: H - M.bottom, class: "axis-line" }, svg);
    el("line", { x1: M.left, x2: W - M.right, y1: H - M.bottom, y2: H - M.bottom, class: "axis-line" }, svg);

    const bw = 110, gap = (plotW - bw * costData.length) / (costData.length + 1);
    const baseY = H - M.bottom;

    costData.forEach((d, i) => {
      const x = M.left + gap + i * (bw + gap);
      const y = yScale(d.value);
      const color = getComputedStyle(document.querySelector(".viz-root")).getPropertyValue(d.colorVar);
      const rect = el("rect", { x, y, width: bw, height: baseY - y, rx: 4, ry: 4, class: "bar-rect", fill: color }, svg);
      el("text", { x: x + bw / 2, y: y - 10, class: "bar-value", "text-anchor": "middle" }, svg).textContent = "$" + d.value.toFixed(2);
      el("text", { x: x + bw / 2, y: baseY + 22, class: "bar-cat", "text-anchor": "middle" }, svg).textContent = d.label;
      const deltaPct = i === 0 ? null : ((d.value / costData[0].value - 1) * 100).toFixed(1);
      const html = `<div class="t-val">$${d.value.toFixed(4)}</div>
        <div class="t-sub">${d.label}${deltaPct !== null ? " · " + deltaPct + "% vs logged" : ""}</div>`;
      rect.addEventListener("pointerenter", e => showTip(e, html));
      rect.addEventListener("pointermove", moveTip);
      rect.addEventListener("pointerleave", hideTip);
      rect.addEventListener("focus", e => showTip(e, html));
      rect.addEventListener("blur", hideTip);
      rect.setAttribute("tabindex", "0");
    });

    const tbody = document.querySelector("#bars-table tbody");
    costData.forEach((d, i) => {
      const tr = document.createElement("tr");
      const pct = i === 0 ? "—" : ((d.value / costData[0].value - 1) * 100).toFixed(1) + "%";
      [d.label, "$" + d.value.toFixed(2), pct].forEach((c, j) => {
        const td = document.createElement("td");
        if (j >= 1) td.className = "num";
        td.textContent = c;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
  })();
})();

