  // ---------------- Panel B: cost-quality frontier (adoption sweep) ----------------
  // From rule_based_router/results/frontier.csv (frontier.py) — real quality_score_est
  // swapped in for baseline/scripts/plot_frontier.py's placeholder. See that script's
  // docstring for exactly what's measured vs. estimated at each point.
  const frontierData = [
    { frac: 0.0, cost: 87.5194, quality: 0.9707, nScored: 762, nEst: 0,   nExcl: 238 },
    { frac: 0.1, cost: 88.5787, quality: 0.9697, nScored: 779, nEst: 50,  nExcl: 221 },
    { frac: 0.2, cost: 89.2137, quality: 0.9701, nScored: 785, nEst: 90,  nExcl: 215 },
    { frac: 0.3, cost: 88.8860, quality: 0.9709, nScored: 792, nEst: 146, nExcl: 208 },
    { frac: 0.4, cost: 86.9782, quality: 0.9708, nScored: 799, nEst: 217, nExcl: 201 },
    { frac: 0.5, cost: 84.5585, quality: 0.9739, nScored: 813, nEst: 298, nExcl: 187 },
    { frac: 0.6, cost: 81.8711, quality: 0.9756, nScored: 835, nEst: 382, nExcl: 165 },
    { frac: 0.7, cost: 78.2856, quality: 0.9732, nScored: 862, nEst: 479, nExcl: 138 },
    { frac: 0.8, cost: 73.5293, quality: 0.9720, nScored: 879, nEst: 579, nExcl: 121 },
    { frac: 0.9, cost: 67.5678, quality: 0.9694, nScored: 910, nEst: 678, nExcl: 90  },
    { frac: 1.0, cost: 54.0248, quality: 0.9661, nScored: 937, nEst: 775, nExcl: 63  },
  ];

  (function renderFrontier() {
    const svg = document.getElementById("frontier");
    const W = 900, H = 380;
    const M = { top: 16, right: 24, bottom: 44, left: 52 };
    const plotW = W - M.left - M.right, plotH = H - M.top - M.bottom;

    const costMax = Math.max(...frontierData.map(d => d.cost));
    const costMin = Math.min(...frontierData.map(d => d.cost));
    const xPad = (costMax - costMin) * 0.10;
    const xScale = c => M.left + ((c - costMin + xPad) / (costMax - costMin + 2 * xPad)) * plotW;
    const qMin = 0.94, qMax = 0.99;
    const yScale = q => M.top + (1 - (q - qMin) / (qMax - qMin)) * plotH;

    for (let q = 0.94; q <= 0.9901; q += 0.01) {
      const y = yScale(q);
      el("line", { x1: M.left, x2: W - M.right, y1: y, y2: y, class: "grid-line" }, svg);
      el("text", { x: M.left - 8, y: y + 3.5, class: "tick-label", "text-anchor": "end" }, svg).textContent = q.toFixed(2);
    }
    const xTicks = [55, 60, 65, 70, 75, 80, 85, 90].filter(v => v >= costMin - xPad && v <= costMax + xPad);
    xTicks.forEach(v => {
      const x = xScale(v);
      el("text", { x, y: H - M.bottom + 20, class: "tick-label", "text-anchor": "middle" }, svg).textContent = "$" + v;
    });
    el("line", { x1: M.left, x2: M.left, y1: M.top, y2: H - M.bottom, class: "axis-line" }, svg);
    el("line", { x1: M.left, x2: W - M.right, y1: H - M.bottom, y2: H - M.bottom, class: "axis-line" }, svg);
    el("text", { x: (M.left + W - M.right) / 2, y: H - 4, class: "axis-label", "text-anchor": "middle" }, svg).textContent = "Total cost across 1,000 tasks (USD)";
    el("text", { x: 14, y: M.top - 2, class: "axis-label" }, svg).textContent = "Avg. quality (est., note zoomed 0.94–0.99 axis)";

    // path in adoption-order (not cost-sorted) — the real, non-monotonic route
    const pathD = frontierData.map((d, i) => `${i === 0 ? "M" : "L"} ${xScale(d.cost)} ${yScale(d.quality)}`).join(" ");
    el("path", { d: pathD, fill: "none", stroke: "var(--series-ours)", "stroke-width": 2, "stroke-linejoin": "round", "stroke-linecap": "round" }, svg);

    frontierData.forEach(d => {
      const cx = xScale(d.cost), cy = yScale(d.quality);
      el("circle", { cx, cy, r: 5, class: "dot", fill: "var(--series-ours)" }, svg);
      const hit = el("circle", { cx, cy, r: 12, class: "hit" }, svg);
      if (d.frac === 0 || d.frac === 0.5 || d.frac === 1) {
        el("text", { x: cx, y: cy - 12, class: "bucket-label", "text-anchor": "middle" }, svg)
          .textContent = Math.round(d.frac * 100) + "% adopted";
      }
      const html = `<div class="t-val">${Math.round(d.frac * 100)}% adopted</div>
        <div class="t-sub">$${d.cost.toFixed(2)} total · ${d.quality.toFixed(4)} avg quality</div>
        <div class="t-sub">n scored ${d.nScored} (of which ${d.nEst} estimated) · n excluded ${d.nExcl}</div>`;
      hit.addEventListener("pointerenter", e => showTip(e, html));
      hit.addEventListener("pointermove", moveTip);
      hit.addEventListener("pointerleave", hideTip);
      hit.addEventListener("focus", e => showTip(e, html));
      hit.addEventListener("blur", hideTip);
      hit.setAttribute("tabindex", "0");
    });

    const tbody = document.querySelector("#frontier-table tbody");
    frontierData.forEach(d => {
      const tr = document.createElement("tr");
      const cells = [Math.round(d.frac * 100) + "%", "$" + d.cost.toFixed(2), d.quality.toFixed(4), String(d.nScored), String(d.nEst), String(d.nExcl)];
      cells.forEach(c => {
        const td = document.createElement("td");
        td.className = "num";
        td.textContent = c;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
  })();
})();
